// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (GET /admin/accounts)
	AdminListAccounts(w http.ResponseWriter, r *http.Request)
	// AdminCreateAccount Import an account. /quota and /v1/models must both succeed before it is saved.
	// (POST /admin/accounts)
	AdminCreateAccount(w http.ResponseWriter, r *http.Request)
	// AdminValidateAccount Check a connection without saving anything (the import dialog's first step).
	// (POST /admin/accounts/validate)
	AdminValidateAccount(w http.ResponseWriter, r *http.Request)
	// AdminDeleteAccount Delete an account (soft delete).
	// (DELETE /admin/accounts/{accountId})
	AdminDeleteAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)

	// (GET /admin/accounts/{accountId})
	AdminGetAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// AdminUpdateAccount Edit an account. The edited connection is validated like an import; saving clears the error state.
	// (PATCH /admin/accounts/{accountId})
	AdminUpdateAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// AdminGetAccountCostCompare Upstream cost per time bucket as seen by cpa-quota and by this bridge.
	// (GET /admin/accounts/{accountId}/cost-compare)
	AdminGetAccountCostCompare(w http.ResponseWriter, r *http.Request, accountId AccountId, params AdminGetAccountCostCompareParams)
	// AdminSetAccountEnabled Enable or disable; enabling also clears the error state.
	// (PUT /admin/accounts/{accountId}/enabled)
	AdminSetAccountEnabled(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// AdminGetAccountEstimate The account's row of the cpa-quota `estimates` table (read only).
	// (GET /admin/accounts/{accountId}/estimate)
	AdminGetAccountEstimate(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// AdminGetAccountKTrend Rows of the cpa-quota `k_trend_daily` table for the account (read only).
	// (GET /admin/accounts/{accountId}/k-trend)
	AdminGetAccountKTrend(w http.ResponseWriter, r *http.Request, accountId AccountId, params AdminGetAccountKTrendParams)
	// AdminGetAccountQuotaSeries Reported utilization of one window over time (cpa-quota `quota_report_windows`, read only).
	// (GET /admin/accounts/{accountId}/quota-series)
	AdminGetAccountQuotaSeries(w http.ResponseWriter, r *http.Request, accountId AccountId, params AdminGetAccountQuotaSeriesParams)
	// AdminTestAccount Call /quota and /v1/models now; a full pass clears the error state and cooldown.
	// (POST /admin/accounts/{accountId}/test)
	AdminTestAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)

	// (GET /admin/audit-logs)
	AdminListAuditLogs(w http.ResponseWriter, r *http.Request, params AdminListAuditLogsParams)
	// AdminEvents Server-sent events across replicas.
	// (GET /admin/events)
	AdminEvents(w http.ResponseWriter, r *http.Request)
	// AdminSetKeyEnabled Enable or disable any user's key (takes effect on every replica at once).
	// (PUT /admin/keys/{keyId}/enabled)
	AdminSetKeyEnabled(w http.ResponseWriter, r *http.Request, keyId KeyId)

	// (GET /admin/ledger)
	AdminListLedger(w http.ResponseWriter, r *http.Request, params AdminListLedgerParams)
	// AdminGetOverview Everything the admin overview page shows, in one call.
	// (GET /admin/overview)
	AdminGetOverview(w http.ResponseWriter, r *http.Request)

	// (GET /admin/plans)
	AdminListPlans(w http.ResponseWriter, r *http.Request)

	// (POST /admin/plans)
	AdminCreatePlan(w http.ResponseWriter, r *http.Request)

	// (DELETE /admin/plans/{planId})
	AdminDeletePlan(w http.ResponseWriter, r *http.Request, planId PlanId)

	// (GET /admin/plans/{planId})
	AdminGetPlan(w http.ResponseWriter, r *http.Request, planId PlanId)
	// AdminUpdatePlan Replace a plan. Existing subscriptions keep the terms they were bought with.
	// (PUT /admin/plans/{planId})
	AdminUpdatePlan(w http.ResponseWriter, r *http.Request, planId PlanId)

	// (GET /admin/prices)
	AdminGetPrices(w http.ResponseWriter, r *http.Request)

	// (POST /admin/prices/refresh)
	AdminRefreshPrices(w http.ResponseWriter, r *http.Request)
	// AdminRunReconcile Run the ledger / balance / charge reconciliation now.
	// (POST /admin/reconcile)
	AdminRunReconcile(w http.ResponseWriter, r *http.Request)

	// (GET /admin/request-logs)
	AdminListRequestLogs(w http.ResponseWriter, r *http.Request, params AdminListRequestLogsParams)

	// (GET /admin/safeguard-events)
	AdminListSafeguardEvents(w http.ResponseWriter, r *http.Request, params AdminListSafeguardEventsParams)

	// (GET /admin/settings)
	AdminGetSettings(w http.ResponseWriter, r *http.Request)
	// AdminUpdateSettings Change some settings; every replica applies them immediately.
	// (PATCH /admin/settings)
	AdminUpdateSettings(w http.ResponseWriter, r *http.Request)

	// (GET /admin/subscriptions)
	AdminListSubscriptions(w http.ResponseWriter, r *http.Request, params AdminListSubscriptionsParams)
	// AdminGrantSubscription Open an active subscription for a user directly on an account, optionally charging the price.
	// (POST /admin/subscriptions)
	AdminGrantSubscription(w http.ResponseWriter, r *http.Request)
	// AdminAssignSubscription Activate a pending subscription on an account (warns, never blocks, on overcommit).
	// (POST /admin/subscriptions/{subscriptionId}/assign)
	AdminAssignSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)

	// (POST /admin/subscriptions/{subscriptionId}/cancel)
	AdminCancelSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)

	// (POST /admin/subscriptions/{subscriptionId}/rebind)
	AdminRebindSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)

	// (GET /admin/usage/summary)
	AdminGetUsageSummary(w http.ResponseWriter, r *http.Request, params AdminGetUsageSummaryParams)

	// (GET /admin/users)
	AdminListUsers(w http.ResponseWriter, r *http.Request, params AdminListUsersParams)

	// (POST /admin/users)
	AdminCreateUser(w http.ResponseWriter, r *http.Request)

	// (DELETE /admin/users/{userId})
	AdminDeleteUser(w http.ResponseWriter, r *http.Request, userId UserId)

	// (GET /admin/users/{userId})
	AdminGetUser(w http.ResponseWriter, r *http.Request, userId UserId)

	// (PATCH /admin/users/{userId})
	AdminUpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// AdminAdjustBalance Top up (admin_topup, amount > 0) or adjust (admin_adjust, signed) a balance.
	// (POST /admin/users/{userId}/balance)
	AdminAdjustBalance(w http.ResponseWriter, r *http.Request, userId UserId)
	// AdminListUserKeys The user's API keys (secrets are never returned here).
	// (GET /admin/users/{userId}/keys)
	AdminListUserKeys(w http.ResponseWriter, r *http.Request, userId UserId)
	// Login Log in with username and password (rate limited).
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session.
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)

	// (GET /balance)
	GetBalance(w http.ResponseWriter, r *http.Request)

	// (GET /keys)
	ListKeys(w http.ResponseWriter, r *http.Request)

	// (POST /keys)
	CreateKey(w http.ResponseWriter, r *http.Request)

	// (DELETE /keys/{keyId})
	DeleteKey(w http.ResponseWriter, r *http.Request, keyId KeyId)

	// (GET /keys/{keyId})
	GetKey(w http.ResponseWriter, r *http.Request, keyId KeyId)

	// (PATCH /keys/{keyId})
	UpdateKey(w http.ResponseWriter, r *http.Request, keyId KeyId)

	// (GET /keys/{keyId}/secret)
	GetKeySecret(w http.ResponseWriter, r *http.Request, keyId KeyId)

	// (GET /ledger)
	ListMyLedger(w http.ResponseWriter, r *http.Request, params ListMyLedgerParams)

	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetMyAvailability Estimated usable amount for the caller (normal / force calls and own plans).
	// (GET /me/availability)
	GetMyAvailability(w http.ResponseWriter, r *http.Request)

	// (POST /me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)

	// (GET /models)
	ListModels(w http.ResponseWriter, r *http.Request)

	// (GET /plans)
	ListPlansOnSale(w http.ResponseWriter, r *http.Request)
	// PurchasePlan Buy a plan with the balance (no overdraft). The subscription waits for an admin to assign an account.
	// (POST /plans/{planId}/purchase)
	PurchasePlan(w http.ResponseWriter, r *http.Request, planId PlanId)

	// (GET /subscriptions)
	ListMySubscriptions(w http.ResponseWriter, r *http.Request)

	// (PUT /subscriptions/{subscriptionId}/auto-renew)
	SetAutoRenew(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)
	// RenewSubscription Renew by one duration (charged to the balance; from now when already expired).
	// (POST /subscriptions/{subscriptionId}/renew)
	RenewSubscription(w http.ResponseWriter, r *http.Request, subscriptionId SubscriptionId)

	// (GET /usage/logs)
	ListMyUsageLogs(w http.ResponseWriter, r *http.Request, params ListMyUsageLogsParams)

	// (GET /usage/summary)
	GetMyUsageSummary(w http.ResponseWriter, r *http.Request, params GetMyUsageSummaryParams)
}

