// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /admin/accounts)
	AdminListAccounts(ctx context.Context, request AdminListAccountsRequestObject) (AdminListAccountsResponseObject, error)
	// AdminCreateAccount Import an account. /quota and /v1/models must both succeed before it is saved.
	// (POST /admin/accounts)
	AdminCreateAccount(ctx context.Context, request AdminCreateAccountRequestObject) (AdminCreateAccountResponseObject, error)
	// AdminValidateAccount Check a connection without saving anything (the import dialog's first step).
	// (POST /admin/accounts/validate)
	AdminValidateAccount(ctx context.Context, request AdminValidateAccountRequestObject) (AdminValidateAccountResponseObject, error)
	// AdminDeleteAccount Delete an account (soft delete).
	// (DELETE /admin/accounts/{accountId})
	AdminDeleteAccount(ctx context.Context, request AdminDeleteAccountRequestObject) (AdminDeleteAccountResponseObject, error)

	// (GET /admin/accounts/{accountId})
	AdminGetAccount(ctx context.Context, request AdminGetAccountRequestObject) (AdminGetAccountResponseObject, error)
	// AdminUpdateAccount Edit an account. The edited connection is validated like an import; saving clears the error state.
	// (PATCH /admin/accounts/{accountId})
	AdminUpdateAccount(ctx context.Context, request AdminUpdateAccountRequestObject) (AdminUpdateAccountResponseObject, error)
	// AdminGetAccountCostCompare Upstream cost per time bucket as seen by cpa-quota and by this bridge.
	// (GET /admin/accounts/{accountId}/cost-compare)
	AdminGetAccountCostCompare(ctx context.Context, request AdminGetAccountCostCompareRequestObject) (AdminGetAccountCostCompareResponseObject, error)
	// AdminSetAccountEnabled Enable or disable; enabling also clears the error state.
	// (PUT /admin/accounts/{accountId}/enabled)
	AdminSetAccountEnabled(ctx context.Context, request AdminSetAccountEnabledRequestObject) (AdminSetAccountEnabledResponseObject, error)
	// AdminGetAccountEstimate The account's row of the cpa-quota `estimates` table (read only).
	// (GET /admin/accounts/{accountId}/estimate)
	AdminGetAccountEstimate(ctx context.Context, request AdminGetAccountEstimateRequestObject) (AdminGetAccountEstimateResponseObject, error)
	// AdminGetAccountKTrend Rows of the cpa-quota `k_trend_daily` table for the account (read only).
	// (GET /admin/accounts/{accountId}/k-trend)
	AdminGetAccountKTrend(ctx context.Context, request AdminGetAccountKTrendRequestObject) (AdminGetAccountKTrendResponseObject, error)
	// AdminGetAccountQuotaSeries Reported utilization of one window over time (cpa-quota `quota_report_windows`, read only).
	// (GET /admin/accounts/{accountId}/quota-series)
	AdminGetAccountQuotaSeries(ctx context.Context, request AdminGetAccountQuotaSeriesRequestObject) (AdminGetAccountQuotaSeriesResponseObject, error)
	// AdminTestAccount Call /quota and /v1/models now; a full pass clears the error state and cooldown.
	// (POST /admin/accounts/{accountId}/test)
	AdminTestAccount(ctx context.Context, request AdminTestAccountRequestObject) (AdminTestAccountResponseObject, error)

	// (GET /admin/audit-logs)
	AdminListAuditLogs(ctx context.Context, request AdminListAuditLogsRequestObject) (AdminListAuditLogsResponseObject, error)
	// AdminEvents Server-sent events across replicas.
	// (GET /admin/events)
	AdminEvents(ctx context.Context, request AdminEventsRequestObject) (AdminEventsResponseObject, error)
	// AdminSetKeyEnabled Enable or disable any user's key (takes effect on every replica at once).
	// (PUT /admin/keys/{keyId}/enabled)
	AdminSetKeyEnabled(ctx context.Context, request AdminSetKeyEnabledRequestObject) (AdminSetKeyEnabledResponseObject, error)

	// (GET /admin/ledger)
	AdminListLedger(ctx context.Context, request AdminListLedgerRequestObject) (AdminListLedgerResponseObject, error)
	// AdminGetOverview Everything the admin overview page shows, in one call.
	// (GET /admin/overview)
	AdminGetOverview(ctx context.Context, request AdminGetOverviewRequestObject) (AdminGetOverviewResponseObject, error)

	// (GET /admin/plans)
	AdminListPlans(ctx context.Context, request AdminListPlansRequestObject) (AdminListPlansResponseObject, error)

	// (POST /admin/plans)
	AdminCreatePlan(ctx context.Context, request AdminCreatePlanRequestObject) (AdminCreatePlanResponseObject, error)

	// (DELETE /admin/plans/{planId})
	AdminDeletePlan(ctx context.Context, request AdminDeletePlanRequestObject) (AdminDeletePlanResponseObject, error)

	// (GET /admin/plans/{planId})
	AdminGetPlan(ctx context.Context, request AdminGetPlanRequestObject) (AdminGetPlanResponseObject, error)
	// AdminUpdatePlan Replace a plan. Existing subscriptions keep the terms they were bought with.
	// (PUT /admin/plans/{planId})
	AdminUpdatePlan(ctx context.Context, request AdminUpdatePlanRequestObject) (AdminUpdatePlanResponseObject, error)

	// (GET /admin/prices)
	AdminGetPrices(ctx context.Context, request AdminGetPricesRequestObject) (AdminGetPricesResponseObject, error)

	// (POST /admin/prices/refresh)
	AdminRefreshPrices(ctx context.Context, request AdminRefreshPricesRequestObject) (AdminRefreshPricesResponseObject, error)
	// AdminRunReconcile Run the ledger / balance / charge reconciliation now.
	// (POST /admin/reconcile)
	AdminRunReconcile(ctx context.Context, request AdminRunReconcileRequestObject) (AdminRunReconcileResponseObject, error)

	// (GET /admin/request-logs)
	AdminListRequestLogs(ctx context.Context, request AdminListRequestLogsRequestObject) (AdminListRequestLogsResponseObject, error)

	// (GET /admin/safeguard-events)
	AdminListSafeguardEvents(ctx context.Context, request AdminListSafeguardEventsRequestObject) (AdminListSafeguardEventsResponseObject, error)

	// (GET /admin/settings)
	AdminGetSettings(ctx context.Context, request AdminGetSettingsRequestObject) (AdminGetSettingsResponseObject, error)
	// AdminUpdateSettings Change some settings; every replica applies them immediately.
	// (PATCH /admin/settings)
	AdminUpdateSettings(ctx context.Context, request AdminUpdateSettingsRequestObject) (AdminUpdateSettingsResponseObject, error)

	// (GET /admin/subscriptions)
	AdminListSubscriptions(ctx context.Context, request AdminListSubscriptionsRequestObject) (AdminListSubscriptionsResponseObject, error)
	// AdminGrantSubscription Open an active subscription for a user directly on an account, optionally charging the price.
	// (POST /admin/subscriptions)
	AdminGrantSubscription(ctx context.Context, request AdminGrantSubscriptionRequestObject) (AdminGrantSubscriptionResponseObject, error)
	// AdminAssignSubscription Activate a pending subscription on an account (warns, never blocks, on overcommit).
	// (POST /admin/subscriptions/{subscriptionId}/assign)
	AdminAssignSubscription(ctx context.Context, request AdminAssignSubscriptionRequestObject) (AdminAssignSubscriptionResponseObject, error)

	// (POST /admin/subscriptions/{subscriptionId}/cancel)
	AdminCancelSubscription(ctx context.Context, request AdminCancelSubscriptionRequestObject) (AdminCancelSubscriptionResponseObject, error)

	// (POST /admin/subscriptions/{subscriptionId}/rebind)
	AdminRebindSubscription(ctx context.Context, request AdminRebindSubscriptionRequestObject) (AdminRebindSubscriptionResponseObject, error)

	// (GET /admin/usage/summary)
	AdminGetUsageSummary(ctx context.Context, request AdminGetUsageSummaryRequestObject) (AdminGetUsageSummaryResponseObject, error)

	// (GET /admin/users)
	AdminListUsers(ctx context.Context, request AdminListUsersRequestObject) (AdminListUsersResponseObject, error)

	// (POST /admin/users)
	AdminCreateUser(ctx context.Context, request AdminCreateUserRequestObject) (AdminCreateUserResponseObject, error)

	// (DELETE /admin/users/{userId})
	AdminDeleteUser(ctx context.Context, request AdminDeleteUserRequestObject) (AdminDeleteUserResponseObject, error)

	// (GET /admin/users/{userId})
	AdminGetUser(ctx context.Context, request AdminGetUserRequestObject) (AdminGetUserResponseObject, error)

	// (PATCH /admin/users/{userId})
	AdminUpdateUser(ctx context.Context, request AdminUpdateUserRequestObject) (AdminUpdateUserResponseObject, error)
	// AdminAdjustBalance Top up (admin_topup, amount > 0) or adjust (admin_adjust, signed) a balance.
	// (POST /admin/users/{userId}/balance)
	AdminAdjustBalance(ctx context.Context, request AdminAdjustBalanceRequestObject) (AdminAdjustBalanceResponseObject, error)
	// AdminListUserKeys The user's API keys (secrets are never returned here).
	// (GET /admin/users/{userId}/keys)
	AdminListUserKeys(ctx context.Context, request AdminListUserKeysRequestObject) (AdminListUserKeysResponseObject, error)
	// Login Log in with username and password (rate limited).
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session.
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)

	// (GET /balance)
	GetBalance(ctx context.Context, request GetBalanceRequestObject) (GetBalanceResponseObject, error)

	// (GET /keys)
	ListKeys(ctx context.Context, request ListKeysRequestObject) (ListKeysResponseObject, error)

	// (POST /keys)
	CreateKey(ctx context.Context, request CreateKeyRequestObject) (CreateKeyResponseObject, error)

	// (DELETE /keys/{keyId})
	DeleteKey(ctx context.Context, request DeleteKeyRequestObject) (DeleteKeyResponseObject, error)

	// (GET /keys/{keyId})
	GetKey(ctx context.Context, request GetKeyRequestObject) (GetKeyResponseObject, error)

	// (PATCH /keys/{keyId})
	UpdateKey(ctx context.Context, request UpdateKeyRequestObject) (UpdateKeyResponseObject, error)

	// (GET /keys/{keyId}/secret)
	GetKeySecret(ctx context.Context, request GetKeySecretRequestObject) (GetKeySecretResponseObject, error)

	// (GET /ledger)
	ListMyLedger(ctx context.Context, request ListMyLedgerRequestObject) (ListMyLedgerResponseObject, error)

	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetMyAvailability Estimated usable amount for the caller (normal / force calls and own plans).
	// (GET /me/availability)
	GetMyAvailability(ctx context.Context, request GetMyAvailabilityRequestObject) (GetMyAvailabilityResponseObject, error)

	// (POST /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)

	// (GET /models)
	ListModels(ctx context.Context, request ListModelsRequestObject) (ListModelsResponseObject, error)

	// (GET /plans)
	ListPlansOnSale(ctx context.Context, request ListPlansOnSaleRequestObject) (ListPlansOnSaleResponseObject, error)
	// PurchasePlan Buy a plan with the balance (no overdraft). The subscription waits for an admin to assign an account.
	// (POST /plans/{planId}/purchase)
	PurchasePlan(ctx context.Context, request PurchasePlanRequestObject) (PurchasePlanResponseObject, error)

	// (GET /subscriptions)
	ListMySubscriptions(ctx context.Context, request ListMySubscriptionsRequestObject) (ListMySubscriptionsResponseObject, error)

	// (PUT /subscriptions/{subscriptionId}/auto-renew)
	SetAutoRenew(ctx context.Context, request SetAutoRenewRequestObject) (SetAutoRenewResponseObject, error)
	// RenewSubscription Renew by one duration (charged to the balance; from now when already expired).
	// (POST /subscriptions/{subscriptionId}/renew)
	RenewSubscription(ctx context.Context, request RenewSubscriptionRequestObject) (RenewSubscriptionResponseObject, error)

	// (GET /usage/logs)
	ListMyUsageLogs(ctx context.Context, request ListMyUsageLogsRequestObject) (ListMyUsageLogsResponseObject, error)

	// (GET /usage/summary)
	GetMyUsageSummary(ctx context.Context, request GetMyUsageSummaryRequestObject) (GetMyUsageSummaryResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

